import { randomUUID } from 'crypto'
import type { HookEvent } from '@thyrox/headless-sdk/agentSdkTypes.js'
import { query } from '../query.js'
import { logEvent } from '@thyrox/local-observability'
import type { AnalyticsMetadata_I_VERIFIED_THIS_IS_NOT_CODE_OR_FILEPATHS } from '../eventMetadata.js'
import type { ToolUseContext } from '@thyrox/tool-registry/Tool.js'
import { type Tool, toolMatchesName } from '@thyrox/tool-registry/Tool.js'
import { SYNTHETIC_OUTPUT_TOOL_NAME } from '@thyrox/tool-registry/tools/SyntheticOutputTool/SyntheticOutputTool.js'
import { ALL_AGENT_DISALLOWED_TOOLS } from '@thyrox/tool-registry/runtime'
import { asAgentId } from '../idTypes'
import type { Message } from '../messageShapes'
import { createAbortController } from '../abortController.js'
import { createAttachmentMessage } from '../attachments.js'
import { createCombinedAbortSignal } from '../combinedAbortSignal.js'
import { logForDebugging } from '@thyrox/local-observability/debug.js'
import { errorMessage } from '@thyrox/local-observability/errorHelpers.js'
import type { HookResult } from '../hooks.js'
import { createUserMessage, handleMessageFromStream } from '../messages.js'
import { getSmallFastModel } from '@thyrox/provider/model.js'
import { hasPermissionsToUseTool } from '@thyrox/permission/permissions'
import { getAgentTranscriptPath, getTranscriptPath } from '@thyrox/storage/sessionStorage.js'
import type { AgentHook } from '@thyrox/config/types'
import { jsonStringify } from '@thyrox/local-observability/slowOperations.js'
import { asSystemPrompt } from '@thyrox/provider/systemPromptType.js'
import {
  addArgumentsToPrompt,
  createStructuredOutputTool,
  hookResponseSchema,
  registerStructuredOutputEnforcement,
} from './hookHelpers.js'
import { clearSessionHooks } from './sessionHooks.js'

/**
 * Execute an agent-based hook using a multi-turn LLM query
 */
export async function execAgentHook(
  hook: AgentHook,
  hookName: string,
  hookEvent: HookEvent,
  jsonInput: string,
  signal: AbortSignal,
  toolUseContext: ToolUseContext,
  toolUseID: string | undefined,
  // Kept for signature stability with the other exec*Hook functions.
  // Was used by hook.prompt(messages) before the .transform() was removed
  // (CC-79) — the only consumer of that was ExitPlanModeV2Tool's
  // programmatic construction, since refactored into VerifyPlanExecutionTool.
  _messages: Message[],
  agentName?: string,
): Promise<HookResult> {
  const effectiveToolUseID = toolUseID || `hook-${randomUUID()}`

  // Get transcript path from context
  const transcriptPath = toolUseContext.agentId
    ? getAgentTranscriptPath(toolUseContext.agentId)
    : getTranscriptPath()
  const hookStartTime = Date.now()
  try {
    // Replace $ARGUMENTS with the JSON input
    const processedPrompt = addArgumentsToPrompt(hook.prompt, jsonInput)
    logForDebugging(
      `Hooks: Processing agent hook with prompt: ${processedPrompt}`,
    )

    // Create user message directly - no need for processUserInput which would
    // trigger UserPromptSubmit hooks and cause infinite recursion
    const userMessage = createUserMessage({ content: processedPrompt })
    const agentMessages = [userMessage]

    logForDebugging(
      `Hooks: Starting agent query with ${agentMessages.length} messages`,
    )

    // Setup timeout and combine with parent signal
    const hookTimeoutMs = hook.timeout ? hook.timeout * 1000 : 60000
    const hookAbortController = createAbortController()

    // Combine parent signal with timeout, and have it abort our controller
    const { signal: parentTimeoutSignal, cleanup: cleanupCombinedSignal } =
      createCombinedAbortSignal(signal, { timeoutMs: hookTimeoutMs })
    const onParentTimeout = () => hookAbortController.abort()
    parentTimeoutSignal.addEventListener('abort', onParentTimeout)

    // Combined signal is just our controller's signal now
    const combinedSignal = hookAbortController.signal

    try {
      // Create StructuredOutput tool with our schema
      const structuredOutputTool = createStructuredOutputTool()

      // Filter out any existing StructuredOutput tool to avoid duplicates with different schemas
      // (e.g., when parent context has a StructuredOutput tool from --json-schema flag)
      const filteredTools = toolUseContext.options.tools.filter(
        tool => !toolMatchesName(tool, SYNTHETIC_OUTPUT_TOOL_NAME),
      )

      // Use all available tools plus our structured output tool
      // Filter out disallowed agent tools to prevent stop hook agents from spawning subagents
      // or entering plan mode, and filter out duplicate StructuredOutput tools
      const tools: Tool[] = [
        ...filteredTools.filter(
          tool => !ALL_AGENT_DISALLOWED_TOOLS.has(tool.name),
        ),
        structuredOutputTool,
      ]

      const systemPrompt = asSystemPrompt([
        `You are verifying a stop condition in Claude Code. Your task is to verify that the agent completed the given plan. The conversation transcript is available at: ${transcriptPath}\nYou can read this file to analyze the conversation history if needed.

Use the available tools to inspect the codebase and verify the condition.
Use as few steps as possible - be efficient and direct.

When done, return your result using the ${SYNTHETIC_OUTPUT_TOOL_NAME} tool with:
- ok: true if the condition is met
- ok: false with reason if the condition is not met`,
      ])

      const model = hook.model ?? getSmallFastModel()
      const MAX_AGENT_TURNS = 50

      // Create unique agentId for this hook agent
      const hookAgentId = asAgentId(`hook-agent-${randomUUID()}`)

      // Create a modified toolUseContext for the agent
      const agentToolUseContext: ToolUseContext = {
        ...toolUseContext,
        agentId: hookAgentId,
        abortController: hookAbortController,
        options: {
          ...toolUseContext.options,
          tools,
          mainLoopModel: model,
          isNonInteractiveSession: true,
          thinkingConfig: { type: 'disabled' as const },
        },
        setInProgressToolUseIDs: () => {},
        getAppState() {
          const appState = toolUseContext.getAppState()
          // Add session rule to allow reading transcript file
          const existingSessionRules =
            appState.toolPermissionContext.alwaysAllowRules.session ?? []
          return {
            ...appState,
            toolPermissionContext: {
              ...appState.toolPermissionContext,
              mode: 'dontAsk' as const,
              alwaysAllowRules: {
                ...appState.toolPermissionContext.alwaysAllowRules,
                session: [...existingSessionRules, `Read(/${transcriptPath})`],
              },
            },
          }
        },
      }

      // Register a session-level stop hook to enforce structured output
      registerStructuredOutputEnforcement(
        toolUseContext.setAppState,
        hookAgentId,
      )

      let structuredOutputResult: { ok: boolean; reason?: string } | null = null
      let turnCount = 0
      let hitMaxTurns = false

      // Use query() for multi-turn execution
      for await (const message of query({
        messages: agentMessages,
        systemPrompt,
        userContext: {},
        systemContext: {},
        canUseTool: hasPermissionsToUseTool,
        toolUseContext: agentToolUseContext,
        querySource: 'hook_agent',
      })) {
        // Process stream events to update response length in the spinner
        handleMessageFromStream(
          message,
          () => {}, // onMessage - we handle messages below
          newContent =>
            toolUseContext.setResponseLength(
              length => length + newContent.length,
            ),
          toolUseContext.setStreamMode ?? (() => {}),
          () => {}, // onStreamingToolUses - not needed for hooks
        )

        // Skip streaming events for further processing
        if (
          message.type === 'stream_event' ||
          message.type === 'stream_request_start'
        ) {
          continue
        }

        // Count assistant turns
        if (message.type === 'assistant') {
          turnCount++

          // Check if we've hit the turn limit
          if (turnCount >= MAX_AGENT_TURNS) {
            hitMaxTurns = true
            logForDebugging(
              `Hooks: Agent turn ${turnCount} hit max turns, aborting`,
            )
            hookAbortController.abort()
            break
          }
        }

        // Check for structured output in attachments
        if (message.type === 'attachment') {
          const att = (message as typeof message & {
            attachment: { type: string; data?: unknown }
          }).attachment
          if (att.type !== 'structured_output') continue
          const parsed = hookResponseSchema().safeParse(att.data)
          if (parsed.success) {
            structuredOutputResult = parsed.data
            logForDebugging(
              `Hooks: Got structured output: ${jsonStringify(structuredOutputResult)}`,
            )
            // Got structured output, abort and exit
            hookAbortController.abort()
            break
          }
        }
      }

      parentTimeoutSignal.removeEventListener('abort', onParentTimeout)
      cleanupCombinedSignal()

      // Clean up the session hook we registered for this agent
      clearSessionHooks(toolUseContext.setAppState, hookAgentId)

      // Check if we got a result
      if (!structuredOutputResult) {
        // If we hit max turns, just log and return cancelled (no UI message)
        if (hitMaxTurns) {
          logForDebugging(
            `Hooks: Agent hook did not complete within ${MAX_AGENT_TURNS} turns`,
          )
          logEvent('tengu_agent_stop_hook_max_turns', {
            durationMs: Date.now() - hookStartTime,
            turnCount,
            agentName:
              agentName as AnalyticsMetadata_I_VERIFIED_THIS_IS_NOT_CODE_OR_FILEPATHS,
          })
          const result = {
            hook,
            outcome: 'cancelled',
          }
          return result
        }

        // For other cases (e.g., agent finished without calling structured output tool),
        // just log and return cancelled (don't show error to user)
        logForDebugging(`Hooks: Agent hook did not return structured output`)
        logEvent('tengu_agent_stop_hook_error', {
          durationMs: Date.now() - hookStartTime,
          turnCount,
          errorType: 1, // 1 = no structured output
          agentName:
            agentName as AnalyticsMetadata_I_VERIFIED_THIS_IS_NOT_CODE_OR_FILEPATHS,
        })
        const result = {
          hook,
          outcome: 'cancelled',
        }
        return result
      }

      // Return result based on structured output
      if (!structuredOutputResult.ok) {
        logForDebugging(
          `Hooks: Agent hook condition was not met: ${structuredOutputResult.reason}`,
        )
        const result = {
          hook,
          outcome: 'blocking',
          blockingError: {
            blockingError: `Agent hook condition was not met: ${structuredOutputResult.reason}`,
            command: hook.prompt,
          },
        }
        return result
      }

      // Condition was met
      logForDebugging(`Hooks: Agent hook condition was met`)
      logEvent('tengu_agent_stop_hook_success', {
        durationMs: Date.now() - hookStartTime,
        turnCount,
        agentName:
          agentName as AnalyticsMetadata_I_VERIFIED_THIS_IS_NOT_CODE_OR_FILEPATHS,
      })
      const result = {
        hook,
        outcome: 'success',
        message: createAttachmentMessage({
          type: 'hook_success',
          hookName,
          toolUseID: effectiveToolUseID,
          hookEvent,
          content: '',
        }),
      }
      return result
    } catch (error) {
      parentTimeoutSignal.removeEventListener('abort', onParentTimeout)
      cleanupCombinedSignal()

      if (combinedSignal.aborted) {
        const result = {
          hook,
          outcome: 'cancelled',
        }
        return result
      }
      throw error
    }
  } catch (error) {
    const errorMsg = errorMessage(error)
    logForDebugging(`Hooks: Agent hook error: ${errorMsg}`)
    logEvent('tengu_agent_stop_hook_error', {
      durationMs: Date.now() - hookStartTime,
      errorType: 2, // 2 = general error
      agentName:
        agentName as AnalyticsMetadata_I_VERIFIED_THIS_IS_NOT_CODE_OR_FILEPATHS,
    })
    const result = {
      hook,
      outcome: 'non_blocking_error',
      message: createAttachmentMessage({
        type: 'hook_non_blocking_error',
        hookName,
        toolUseID: effectiveToolUseID,
        hookEvent,
        stderr: `Error executing agent hook: ${errorMsg}`,
        stdout: '',
        exitCode: 1,
      }),
    }
    return result
  }
}

/**
 * Ensamblado del prompt de sistema desde `.claude/` (T-022).
 *
 * La lección de :ref:`h-docs-99` es que **el piso no se hereda entero**: el
 * contexto siempre-cargado del cliente mide 126 029 tokens, y ése es el motivo
 * por el que `claude-haiku-4-5` no arranca aquí. Un harness propio que copie esa
 * forma repite el defecto; por eso cada sección declara su coste y el
 * presupuesto es un parámetro, no una consecuencia.
 *
 * Dos decisiones que la referencia ya tomó y que aquí se respetan:
 *
 * 1. **Una regla con `paths:` es condicional.** La doc del cliente lo dice al
 *    revés y por eso importa: *"Rules without a `paths` field are loaded
 *    unconditionally"* — declarar `paths:` es lo que la saca del piso.
 * 2. **El orden importa para la caché.** Lo estable va primero (base, CLAUDE.md)
 *    y lo variable después: la clave de caché es un prefijo, así que una sección
 *    que cambia arriba invalida todo lo de abajo.
 */
import { existsSync, readFileSync, readdirSync } from 'node:fs'
import type { Duty } from './basePrompt.ts'
import { join } from 'node:path'
import { dedupSections } from '@thyrox/context-compression'

export type Section = { name: string; text: string; tokens: number; conditional: boolean }

export type AssembleOptions = {
  /** Raíz del proyecto: de ahí cuelgan `CLAUDE.md` y `.claude/`. */
  root: string
  /**
   * El prompt propio del harness. Nunca se descarta.
   *
   * Una cadena entra como una sección `base`. Una LISTA de deberes entra
   * como una sección por deber, nombrada `base:<deber>` — es la separación
   * por DEBER que A.2.1 pide, y la que hace que retirar uno sea una
   * operación medible. Las dos formas conviven a propósito: obligar a los
   * llamadores a la lista rompería a todos para ganar una separación que se
   * puede tener sin romper a nadie.
   */
  base: string | readonly Duty[]
  /** Ruta del archivo sobre el que se va a trabajar; decide qué reglas condicionales entran. */
  targetPath?: string
  /** Tope de tokens para el prompt entero. Sin él no se descarta nada. */
  budgetTokens?: number
}

export type Assembled = {
  text: string
  sections: Section[]
  dropped: Section[]
  /**
   * Secciones que se retiraron por traer EXACTAMENTE el mismo texto (recorte
   * de espacios aparte) que una anterior. Es el patrón "cheat-sheet
   * (canónico en docs)" de los repos consumidores: varias reglas comparten
   * un preámbulo idéntico, y `dedupSections` lo detecta por texto completo
   * -- no por un prefijo, que produciría falsos positivos entre secciones
   * largas que sólo COMPARTEN el preámbulo (ver `dedupSections` en
   * `@thyrox/context-compression`).
   */
  duplicates: Section[]
  tokens: number
}

/**
 * Estimación de tokens por caracteres.
 *
 * Es una aproximación deliberada — el tokenizador real no está disponible
 * localmente. Su uso legítimo es **decidir un presupuesto**, no publicar una
 * cifra de coste: para eso está la telemetría del transcript, que trae el
 * `usage` que el servicio cobró.
 */
export function estimateTokens(text: string): number {
  if (!text) return 0
  return Math.ceil(text.length / 4)
}

/** El cuerpo y los `paths:` de un archivo de regla, con las dos formas del árbol. */
export function parseRule(raw: string): { body: string; paths: string[] | null } {
  const fenced = /^```ya?ml\r?\n([\s\S]*?)\r?\n```\r?\n?/.exec(raw)
  const dashed = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(raw)
  const match = fenced ?? dashed
  if (!match) return { body: raw, paths: null }
  const body = raw.slice(match[0].length)
  const inner = match[1]
  if (inner === undefined) return { body, paths: null }
  const line = /^\s*paths:\s*(.+)$/m.exec(inner)
  if (!line) return { body, paths: null }
  const captured = line[1]
  if (captured === undefined) return { body, paths: null }
  return { body, paths: splitPaths(captured) }
}

/** `paths: a, b` · `paths: ["a", "b"]` · `paths: a` — las tres formas dan la misma lista. */
function splitPaths(value: string): string[] {
  const trimmed = value.trim().replace(/^\[|\]$/g, '')
  return trimmed
    .split(',')
    .map((p) => p.trim().replace(/^["']|["']$/g, ''))
    .filter(Boolean)
}

/** `**` cruza separadores, `*` no — el mismo criterio que la puerta de permisos. */
export function matchesPath(pattern: string, path: string): boolean {
  const escape = (s: string) => s.replace(/[.+^${}()|[\]\\]/g, '\\$&')
  const body = pattern
    .split('**')
    .map((segment) => escape(segment).replace(/\*/g, '[^/]*'))
    .join('.*')
  return new RegExp(`^${body}$`).test(path)
}

function readTrimmed(path: string): string | null {
  if (!existsSync(path)) return null
  const text = readFileSync(path, 'utf8').trim()
  return text.length ? text : null
}

function section(name: string, text: string, conditional = false): Section {
  return { name, text, tokens: estimateTokens(text), conditional }
}

/** Reúne las secciones candidatas en su orden de caché, y aplica el presupuesto. */
export function assembleSystemPrompt(opts: AssembleOptions): Assembled {
  const rawCandidates: Section[] = typeof opts.base === 'string'
    ? [section('base', opts.base)]
    : opts.base.map((d) => section(`base:${d.name}`, d.text))

  const root = readTrimmed(join(opts.root, 'CLAUDE.md'))
  if (root) rawCandidates.push(section('CLAUDE.md', root))

  const level2 = readTrimmed(join(opts.root, '.claude', 'CLAUDE.md'))
  if (level2) rawCandidates.push(section('.claude/CLAUDE.md', level2))

  const rulesDir = join(opts.root, '.claude', 'rules')
  if (existsSync(rulesDir)) {
    const files = readdirSync(rulesDir).filter((f) => f.endsWith('.md')).sort()
    for (const file of files) {
      const raw = readTrimmed(join(rulesDir, file))
      if (!raw) continue
      const { body, paths } = parseRule(raw)
      // Sin `paths:` la regla es del piso; con `paths:` sólo entra si la ruta
      // objetivo casa alguno de sus patrones. Sin ruta objetivo, no entra.
      if (paths) {
        if (!opts.targetPath) continue
        if (!paths.some((p) => matchesPath(p, opts.targetPath as string))) continue
      }
      if (!body.trim()) continue
      rawCandidates.push(section(`.claude/rules/${file}`, body.trim(), paths !== null))
    }
  }

  // El dedupe corre ANTES del presupuesto: una sección duplicada no debe
  // competir por espacio con las que sí aportan texto nuevo.
  const { sections: candidates, duplicates } = dedupSections(rawCandidates)

  const sections: Section[] = []
  const dropped: Section[] = []
  let tokens = 0
  for (const s of candidates) {
    // `base` y `base:<deber>` son el PISO: un presupuesto que pudiera dejar
    // al agente sin identidad o sin restricciones de herramienta estaría
    // decidiendo la conducta, y el tope existe para acotar el contexto, no
    // para eso.
    const isBase = s.name === 'base' || s.name.startsWith('base:')
    if (!isBase && opts.budgetTokens !== undefined && tokens + s.tokens > opts.budgetTokens) {
      dropped.push(s)
      continue
    }
    sections.push(s)
    tokens += s.tokens
  }

  return { text: sections.map((s) => s.text).join('\n\n'), sections, dropped, duplicates, tokens }
}

#!/usr/bin/env bun
/**
 * Interfaz de linea de comandos de `@thyrox/binary`.
 *
 * Subcomandos:
 *   info                 version declarada, secciones, tamano de la tabla
 *   extract [--out R]    escribe el corpus en <R>/<version>/ con MANIFEST
 *   graph [--json]       grafo de imports entre modulos
 *   freshness [--root R] compara el corpus con el ejecutable vivo
 *   reflow <mod> [--out] reformatea un modulo para que sea citable
 *   symbol <chunk> <nombre>... [--root R]
 *                        definiciones completas de cada nombre, por arbol
 *                        sintactico, siguiendo import/export entre chunks
 *
 * Toda salida lleva su denominador. Un conteo sin el no es un resultado: con
 * el alcance oculto, un instrumento ciego y uno correcto publican la misma
 * cifra.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { findSection } from '../src/elf.ts'
import { BUNFS_PREFIX, SECTION_HEADER, deriveVersion, readModuleTable } from '../src/bunfs.ts'
import { buildGraph } from '../src/graph.ts'
import { writeCorpus } from '../src/corpus.ts'
import { corpusVersion, freshness } from '../src/freshness.ts'
import { reflow } from '../src/reflow.ts'
import { resolveSymbol } from '../src/symbol.ts'

const BINARIO_DEFECTO = '/opt/claude-code/bin/claude'
const CORPUS_DEFECTO = '_references/claude-code-bin'
const EXIT_GUARD = 2

/** Muere con 2 y SIN emitir cifra: un 0 aqui seria un verde falso. */
function guard(mensaje: string): never {
  console.error(`ERROR — ${mensaje}. NO se emite un conteo.`)
  process.exit(EXIT_GUARD)
}

function opcion(argv: string[], nombre: string, defecto: string): string {
  const i = argv.indexOf(nombre)
  const valor = argv[i + 1]
  return i >= 0 && valor ? valor : defecto
}

function abrir(argv: string[]) {
  const ruta = opcion(argv, '--bin', BINARIO_DEFECTO)
  if (!existsSync(ruta)) guard(`no existe el ejecutable ${ruta}`)
  const bytes = readFileSync(ruta)
  const seccion = findSection(bytes, '.bun')
  if (seccion === null) guard(`${ruta} no declara una seccion .bun`)
  const payload = bytes.subarray(seccion.offset + SECTION_HEADER, seccion.offset + seccion.size)
  const version = deriveVersion(bytes.subarray(seccion.offset, seccion.offset + seccion.size))
  if (version === null) guard('el payload no declara su version')
  const tabla = readModuleTable(payload)
  if (tabla === null) guard('no se pudo derivar la forma de la tabla de modulos')
  return { ruta, bytes, seccion, payload, version, tabla }
}

const argv = process.argv.slice(2)
const orden = argv[0] ?? 'info'

if (orden === 'info') {
  const { ruta, seccion, version, tabla } = abrir(argv)
  const porTipo = new Map<string, number>()
  for (const e of tabla.entries) {
    const ext = e.name.match(/\.[a-z0-9]+$/i)?.[0] ?? '(sin)'
    porTipo.set(ext, (porTipo.get(ext) ?? 0) + 1)
  }
  const bytes = tabla.entries.reduce((n, e) => n + e.length, 0)
  console.log(`ejecutable  ${ruta}`)
  console.log(`version     ${version}   (declarada por el payload, no por --version)`)
  console.log(`seccion     .bun en ${seccion.offset}, ${seccion.size} B`)
  console.log(`tabla       ${tabla.entries.length} entradas, paso ${tabla.stride}, ${tabla.tableLength} B`)
  console.log(`contenido   ${bytes} B`)
  console.log(`por tipo    ${[...porTipo].sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(' · ')}`)
} else if (orden === 'extract') {
  const { payload, version, tabla } = abrir(argv)
  const raiz = opcion(argv, '--out', CORPUS_DEFECTO)
  const r = writeCorpus(raiz, version, payload, tabla.entries)
  console.log(`escrito ${r.files} archivo(s), ${r.bytes} B en ${r.root}`)
  console.log(`(alcance medido: ${r.files} de ${tabla.entries.length} entradas de la tabla)`)
} else if (orden === 'graph') {
  const { payload, tabla, version } = abrir(argv)
  const g = buildGraph(payload, tabla.entries)
  if (argv.includes('--json')) {
    console.log(JSON.stringify({ version, nodes: Object.fromEntries(g.nodes), edges: g.edges }, null, 2))
  } else {
    const entrada = new Map<string, number>()
    for (const [, ds] of g.nodes) for (const d of ds) entrada.set(d, (entrada.get(d) ?? 0) + 1)
    console.log(`version ${version}: ${g.nodes.size} nodos, ${g.edges} aristas, ${g.dangling.length} destinos colgantes`)
    console.log(`(alcance medido: ${g.nodes.size} de ${tabla.entries.length} entradas — solo los .js declaran imports)`)
    console.log('mas importados:')
    for (const [n, d] of [...entrada].sort((a, b) => b[1] - a[1]).slice(0, 10)) console.log(`  ${String(d).padStart(4)}  ${n}`)
  }
} else if (orden === 'freshness') {
  const { version } = abrir(argv)
  const f = freshness(opcion(argv, '--root', CORPUS_DEFECTO), version)
  console.log(f.reason)
  process.exit(f.stale ? 1 : 0)
} else if (orden === 'reflow') {
  const { payload, tabla } = abrir(argv)
  const nombre = argv[1]
  if (!nombre || nombre.startsWith('--')) guard('falta el nombre del modulo (ej. chunk-vw215j9f.js)')
  const e = tabla.entries.find(x => x.name === BUNFS_PREFIX + nombre || x.name.endsWith('/' + nombre))
  if (!e) guard(`la tabla no declara el modulo ${nombre}`)
  const src = payload.subarray(e.offset, e.offset + e.length).toString('utf8')
  const salida = reflow(src)
  const destino = opcion(argv, '--out', '')
  const linea = (s: string) => s.split('\n')
  console.error(`${nombre}: ${linea(src).length} -> ${linea(salida).length} lineas; ancho medio ${Math.round(src.length / linea(src).length)} -> ${Math.round(salida.length / linea(salida).length)}`)
  if (destino) writeFileSync(destino, salida)
  else process.stdout.write(salida)
} else if (orden === 'symbol') {
  // Sin `--root`, la build más reciente del corpus: un literal fijo dejaba de
  // ser la última en cuanto se extraía otra.
  const ultima = corpusVersion(CORPUS_DEFECTO)
  if (!argv.includes('--root') && ultima === null) guard(`sin builds en ${CORPUS_DEFECTO}; use --root`)
  const raiz = opcion(argv, '--root', `${CORPUS_DEFECTO}/${ultima}/bunfs-root`)
  const [chunk, ...resto] = argv.slice(1)
  const nombres = resto.filter((x, i) => !x.startsWith('--') && resto[i - 1] !== '--root')
  if (!chunk || nombres.length === 0) guard('uso: symbol <chunk> <nombre>... [--root R]')
  if (!existsSync(`${raiz}/${chunk}`)) guard(`no existe ${raiz}/${chunk}`)
  let ausentes = 0
  for (const nombre of nombres) {
    const defs = resolveSymbol(raiz, chunk, nombre)
    if (defs.length === 0) ausentes++
    const alcance = defs.length > 0 && defs.every(d => d.kind === 'method') ? 'de método de clase' : 'de nivel superior'
    console.log(`==== ${nombre}: ${defs.length} definicion(es) ${alcance}`)
    for (const d of defs) console.log(`---- ${d.file} ${d.kind} ${d.name} [${d.start},${d.end})\n${d.text}`)
  }
  console.error(`symbol: ${nombres.length - ausentes} de ${nombres.length} nombre(s) resueltos`)
  process.exit(ausentes > 0 ? 1 : 0)
} else {
  guard(`subcomando desconocido: ${orden}. Use info | extract | graph | freshness | reflow | symbol`)
}

/**
 * Frescura del corpus contra el ejecutable vivo.
 *
 * El hueco que cierra esta medido: las builds 2.1.250, 2.1.251 y 2.1.258
 * quedaron con dos archivos cada una —solo el volcado de `strings`— mientras
 * 2.1.246 tenia 1716. Nadie aviso: el binario se actualiza sin que el
 * repositorio se entere.
 *
 * Las dos versiones se derivan de sitios distintos a proposito. La viva sale
 * del payload; la del corpus, de lo que hay en disco. Ni el nombre de un
 * directorio ni `claude --version` sirven de arbitro: en H-DOCS-455 el
 * contenedor actualizo el ejecutable a media sesion y los dos mintieron.
 */
import { existsSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'
import { MANIFEST } from './corpus.ts'

export type Freshness = { corpus: string | null; live: string; stale: boolean; reason: string }

const SEMVER = /^(\d+)\.(\d+)\.(\d+)(.*)$/

/**
 * La build mas alta **extraida**. `null` si no hay ninguna.
 *
 * El discriminador es el `MANIFEST.tsv`, no la existencia del directorio: el
 * corpus real tiene `2.1.258/` con dos archivos —README y volcado de
 * `strings`— y ninguna extraccion. Contar la carpeta seria un verde que no
 * distingue «extraida» de «tiene carpeta con su nombre».
 */
export function corpusVersion(root: string): string | null {
  if (!existsSync(root)) return null
  const builds = readdirSync(root).filter(n => {
    if (!SEMVER.test(n)) return false
    if (!statSync(join(root, n)).isDirectory()) return false
    return existsSync(join(root, n, MANIFEST))
  })
  return builds.sort(comparaVersion).at(-1) ?? null
}

/**
 * Orden por (mayor, menor, parche) y, a igualdad, por el sufijo.
 *
 * El sufijo NO se puede pasar por `Number`: el corpus tiene
 * `2.1.246-nombrado`, y `Number('246-nombrado')` da `NaN`. Un `NaN` en el
 * comparador deja el orden sin definir, y con eso el gate publico esa carpeta
 * como la build mas alta teniendo 2.1.258 en disco.
 */
function comparaVersion(a: string, b: string): number {
  const pa = SEMVER.exec(a)!
  const pb = SEMVER.exec(b)!
  for (let i = 1; i <= 3; i++) {
    const d = Number(pa[i]) - Number(pb[i])
    if (d !== 0) return d
  }
  return (pa[4] ?? '').localeCompare(pb[4] ?? '')
}

/**
 * Compara y **nombra el motivo**. Un booleano solo no dice que hacer, y ese
 * silencio es lo que dejo el corpus tres builds atras.
 */
export function freshness(root: string, live: string): Freshness {
  const corpus = corpusVersion(root)
  if (corpus === null) {
    return { corpus, live, stale: true, reason: `sin corpus en ${root}; extraer ${live}` }
  }
  if (corpus === live) {
    return { corpus, live, stale: false, reason: `el corpus esta en ${live}` }
  }
  return {
    corpus,
    live,
    stale: true,
    reason: `el corpus llega a ${corpus} y el ejecutable declara ${live}; extraer ${live}`,
  }
}

/**
 * Grafo de dependencias entre los modulos del contenedor.
 *
 * El empaquetador conserva los imports ENTRE chunks —son ficheros distintos
 * dentro del sistema de archivos virtual— aunque haya borrado las fronteras
 * DENTRO de cada uno. Ese grafo es la unica estructura de alto nivel que
 * sobrevive al empaquetado, y es lo que permite decir «este simbolo vive en el
 * chunk que importan estos otros» en vez de «aparece en el volcado».
 *
 * Medido sobre 2.1.258: en una muestra de 400 modulos `.js`, 326 declaran al
 * menos un import y suman 2680 aristas.
 */
import { BUNFS_PREFIX, type ModuleEntry } from './bunfs.ts'

/**
 * Las dos formas que el empaquetador emite. Se exige la palabra clave
 * (`from"…"`) y no la mera aparicion de la raiz virtual: esa cadena tambien
 * sale en mensajes de diagnostico del propio cliente, y contarla inflaria el
 * grafo con aristas inexistentes.
 */
const IMPORT_RE = /\bfrom\s*"\/\$bunfs\/root\/([^"]+)"/g

export type Graph = {
  /** modulo → modulos que importa */
  nodes: Map<string, string[]>
  edges: number
  /** destinos que ningun modulo declara: si hay alguno, el patron leyo de mas */
  dangling: string[]
}

/** Los modulos que `src` importa, sin repetidos y sin el propio `self`. */
export function importsOf(src: string, self?: string): string[] {
  const vistos = new Set<string>()
  for (const m of src.matchAll(IMPORT_RE)) {
    const destino = m[1]
    if (destino === undefined || destino === self) continue
    vistos.add(destino)
  }
  return [...vistos]
}

/** Construye el grafo sobre los modulos `.js` de la tabla. */
export function buildGraph(payload: Buffer, entries: ModuleEntry[]): Graph {
  const js = entries.filter(e => e.name.endsWith('.js'))
  const conocidos = new Set(js.map(e => e.name.slice(BUNFS_PREFIX.length)))
  const nodes = new Map<string, string[]>()
  const dangling = new Set<string>()
  let edges = 0

  for (const e of js) {
    const propio = e.name.slice(BUNFS_PREFIX.length)
    const src = payload.subarray(e.offset, e.offset + e.length).toString('utf8')
    const destinos = importsOf(src, propio)
    for (const d of destinos) if (!conocidos.has(d)) dangling.add(d)
    nodes.set(propio, destinos)
    edges += destinos.length
  }
  return { nodes, edges, dangling: [...dangling] }
}

import memoize from 'lodash-es/memoize.js'
import { basename, dirname, join } from 'path'
import { getInlinePlugins, getSessionId } from './_deps.js'
import type { Command } from './_deps.js'
import { getPluginErrorMessage } from './types.js'
import {
  parseArgumentNames,
  substituteArguments,
} from './_deps.js'
import { logForDebugging } from './_deps.js'
import { EFFORT_LEVELS, parseEffortValue } from './_deps.js'
import { isBareMode } from '../env/utils.js'
import { isENOENT } from './_deps.js'
import {
  coerceDescriptionToString,
  type FrontmatterData,
  parseBooleanFrontmatter,
  parseFrontmatter,
  parseShellFrontmatter,
} from './_deps.js'
import { getFsImplementation, isDuplicatePath } from './_deps.js'
import {
  extractDescriptionFromMarkdown,
  parseSlashCommandToolsFromFrontmatter,
} from './_deps.js'
import { parseUserSpecifiedModel } from './_deps.js'
import { executeShellCommandsInPrompt } from './_deps.js'
import { loadAllPluginsCacheOnly } from './pluginLoader.js'
import { logNameCollision } from './nameCollision.js'
import {
  loadPluginOptions,
  substitutePluginVariables,
  substituteUserConfigInContent,
} from './pluginOptionsStorage.js'
import type { CommandMetadata, PluginManifest } from './schemas.js'
import { walkPluginMarkdown } from './walkPluginMarkdown.js'

// Similar to MarkdownFile but for plugin sources
type PluginMarkdownFile = {
  filePath: string
  baseDir: string
  frontmatter: FrontmatterData
  content: string
}

// Configuration for loading commands or skills
type LoadConfig = {
  isSkillMode: boolean // true when loading from skills/ directory
}

/**
 * Check if a file path is a skill file (SKILL.md)
 */
function isSkillFile(filePath: string): boolean {
  return /^skill\.md$/i.test(basename(filePath))
}

/**
 * Get command name from file path, handling both regular files and skills
 */
function getCommandNameFromFile(
  filePath: string,
  baseDir: string,
  pluginName: string,
): string {
  const isSkill = isSkillFile(filePath)

  if (isSkill) {
    // For skills, use the parent directory name
    const skillDirectory = dirname(filePath)
    const parentOfSkillDir = dirname(skillDirectory)
    const commandBaseName = basename(skillDirectory)

    // Build namespace from parent of skill directory
    const relativePath = parentOfSkillDir.startsWith(baseDir)
      ? parentOfSkillDir.slice(baseDir.length).replace(/^\//, '')
      : ''
    const namespace = relativePath ? relativePath.split('/').join(':') : ''

    return namespace
      ? `${pluginName}:${namespace}:${commandBaseName}`
      : `${pluginName}:${commandBaseName}`
  } else {
    // For regular files, use filename without .md
    const fileDirectory = dirname(filePath)
    const commandBaseName = basename(filePath).replace(/\.md$/, '')

    // Build namespace from file directory
    const relativePath = fileDirectory.startsWith(baseDir)
      ? fileDirectory.slice(baseDir.length).replace(/^\//, '')
      : ''
    const namespace = relativePath ? relativePath.split('/').join(':') : ''

    return namespace
      ? `${pluginName}:${namespace}:${commandBaseName}`
      : `${pluginName}:${commandBaseName}`
  }
}

/**
 * Recursively collects all markdown files from a directory
 */
async function collectMarkdownFiles(
  dirPath: string,
  baseDir: string,
  loadedPaths: Set<string>,
): Promise<PluginMarkdownFile[]> {
  const files: PluginMarkdownFile[] = []
  const fs = getFsImplementation()

  await walkPluginMarkdown(
    dirPath,
    async fullPath => {
      if (isDuplicatePath(fullPath, loadedPaths)) return
      const content = await fs.readFile(fullPath, { encoding: 'utf-8' })
      const { frontmatter, content: markdownContent } = parseFrontmatter(
        content,
        fullPath,
      )
      files.push({
        filePath: fullPath,
        baseDir,
        frontmatter,
        content: markdownContent,
      })
    },
    { stopAtSkillDir: true, logLabel: 'commands' },
  )

  return files
}

/**
 * Transforms plugin markdown files to handle skill directories
 */
function transformPluginSkillFiles(
  files: PluginMarkdownFile[],
): PluginMarkdownFile[] {
  const filesByDir = new Map<string, PluginMarkdownFile[]>()

  for (const file of files) {
    const dir = dirname(file.filePath)
    const dirFiles = filesByDir.get(dir) ?? []
    dirFiles.push(file)
    filesByDir.set(dir, dirFiles)
  }

  const result: PluginMarkdownFile[] = []

  for (const [dir, dirFiles] of filesByDir) {
    const skillFiles = dirFiles.filter(f => isSkillFile(f.filePath))
    if (skillFiles.length > 0) {
      // Use the first skill file if multiple exist
      const skillFile = skillFiles[0]!
      if (skillFiles.length > 1) {
        logForDebugging(
          `Multiple skill files found in ${dir}, using ${basename(skillFile.filePath)}`,
        )
      }
      // Directory has a skill - only include the skill file
      result.push(skillFile)
    } else {
      result.push(...dirFiles)
    }
  }

  return result
}

async function loadCommandsFromDirectory(
  commandsPath: string,
  pluginName: string,
  sourceName: string,
  pluginManifest: PluginManifest,
  pluginPath: string,
  config: LoadConfig = { isSkillMode: false },
  loadedPaths: Set<string> = new Set(),
): Promise<Command[]> {
  // Collect all markdown files
  const markdownFiles = await collectMarkdownFiles(
    commandsPath,
    commandsPath,
    loadedPaths,
  )

  // Apply skill transformation
  const processedFiles = transformPluginSkillFiles(markdownFiles)

  // Convert to commands
  const commands: Command[] = []
  for (const file of processedFiles) {
    const commandName = getCommandNameFromFile(
      file.filePath,
      file.baseDir,
      pluginName,
    )

    const command = createPluginCommand(
      commandName,
      file,
      sourceName,
      pluginManifest,
      pluginPath,
      isSkillFile(file.filePath),
      config,
    )

    if (command) {
      commands.push(command)
    }
  }

  return commands
}

/**
 * Create a Command from a plugin markdown file
 */
function createPluginCommand(
  commandName: string,
  file: PluginMarkdownFile,
  sourceName: string,
  pluginManifest: PluginManifest,
  pluginPath: string,
  isSkill: boolean,
  config: LoadConfig = { isSkillMode: false },
): Command | null {
  try {
    const { frontmatter, content } = file

    const validatedDescription = coerceDescriptionToString(
      frontmatter.description,
      commandName,
    )
    const description =
      validatedDescription ??
      extractDescriptionFromMarkdown(
        content,
        isSkill ? 'Plugin skill' : 'Plugin command',
      )

    // Substitute ${CLAUDE_PLUGIN_ROOT} in allowed-tools before parsing
    const rawAllowedTools = frontmatter['allowed-tools']
    const substitutedAllowedTools =
      typeof rawAllowedTools === 'string'
        ? substitutePluginVariables(rawAllowedTools, {
            path: pluginPath,
            source: sourceName,
          })
        : Array.isArray(rawAllowedTools)
          ? rawAllowedTools.map(tool =>
              typeof tool === 'string'
                ? substitutePluginVariables(tool, {
                    path: pluginPath,
                    source: sourceName,
                  })
                : tool,
            )
          : rawAllowedTools
    const allowedTools = parseSlashCommandToolsFromFrontmatter(
      substitutedAllowedTools,
    )

    const argumentHint = frontmatter['argument-hint'] as string | undefined
    const argumentNames = parseArgumentNames(
      frontmatter.arguments as string | string[] | undefined,
    )
    const whenToUse = frontmatter.when_to_use as string | undefined
    const version = frontmatter.version as string | undefined
    const displayName = frontmatter.name as string | undefined

    // Handle model configuration, resolving aliases like 'haiku', 'sonnet', 'opus'
    const model =
      frontmatter.model === 'inherit'
        ? undefined
        : frontmatter.model
          ? parseUserSpecifiedModel(frontmatter.model as string)
          : undefined

    const effortRaw = frontmatter['effort']
    const effort =
      effortRaw !== undefined ? parseEffortValue(effortRaw) : undefined
    if (effortRaw !== undefined && effort === undefined) {
      logForDebugging(
        `Plugin command ${commandName} has invalid effort '${effortRaw}'. Valid options: ${EFFORT_LEVELS.join(', ')} or an integer`,
      )
    }

    const disableModelInvocation = parseBooleanFrontmatter(
      frontmatter['disable-model-invocation'],
    )

    const userInvocableValue = frontmatter['user-invocable']
    const userInvocable =
      userInvocableValue === undefined
        ? true
        : parseBooleanFrontmatter(userInvocableValue)

    const shell = parseShellFrontmatter(frontmatter.shell, commandName)

    return {
      type: 'prompt',
      name: commandName,
      description,
      hasUserSpecifiedDescription: validatedDescription !== null,
      allowedTools,
      argumentHint,
      argNames: argumentNames.length > 0 ? argumentNames : undefined,
      whenToUse,
      version,
      model,
      effort,
      disableModelInvocation,
      userInvocable,
      contentLength: content.length,
      source: 'plugin' as const,
      loadedFrom: isSkill || config.isSkillMode ? 'plugin' : undefined,
      pluginInfo: {
        pluginManifest,
        repository: sourceName,
      },
      isHidden: !userInvocable,
      progressMessage: isSkill || config.isSkillMode ? 'loading' : 'running',
      userFacingName(): string {
        return displayName || commandName
      },
      async getPromptForCommand(args, context) {
        // For skills from skills/ directory, include base directory
        let finalContent = config.isSkillMode
          ? `Base directory for this skill: ${dirname(file.filePath)}\n\n${content}`
          : content

        finalContent = substituteArguments(
          finalContent,
          args,
          true,
          argumentNames,
        )

        // Replace ${CLAUDE_PLUGIN_ROOT} and ${CLAUDE_PLUGIN_DATA} with their paths
        finalContent = substitutePluginVariables(finalContent, {
          path: pluginPath,
          source: sourceName,
        })

        // Replace ${user_config.X} with saved option values. Sensitive keys
        // resolve to a descriptive placeholder instead — skill content goes to
        // the model prompt and we don't put secrets there.
        if (pluginManifest.userConfig) {
          finalContent = substituteUserConfigInContent(
            finalContent,
            loadPluginOptions(sourceName),
            pluginManifest.userConfig,
          )
        }

        // Replace ${CLAUDE_SKILL_DIR} with this specific skill's directory.
        // Distinct from ${CLAUDE_PLUGIN_ROOT}: a plugin can contain multiple
        // skills, so CLAUDE_PLUGIN_ROOT points to the plugin root while
        // CLAUDE_SKILL_DIR points to the individual skill's subdirectory.
        if (config.isSkillMode) {
          const rawSkillDir = dirname(file.filePath)
          const skillDir =
            process.platform === 'win32'
              ? rawSkillDir.replace(/\\/g, '/')
              : rawSkillDir
          finalContent = finalContent.replace(
            /\$\{CLAUDE_SKILL_DIR\}/g,
            skillDir,
          )
        }

        // Replace ${CLAUDE_SESSION_ID} with the current session ID
        finalContent = finalContent.replace(
          /\$\{CLAUDE_SESSION_ID\}/g,
          getSessionId(),
        )

        finalContent = await executeShellCommandsInPrompt(
          finalContent,
          {
            ...context,
            getAppState() {
              const appState = context.getAppState()
              return {
                ...appState,
                toolPermissionContext: {
                  ...appState.toolPermissionContext,
                  alwaysAllowRules: {
                    ...appState.toolPermissionContext.alwaysAllowRules,
                    command: allowedTools,
                  },
                },
              }
            },
          },
          `/${commandName}`,
          shell,
        )

        return [{ type: 'text', text: finalContent }]
      },
    } satisfies Command
  } catch (error) {
    logForDebugging(
      `Failed to create command from ${file.filePath}: ${error}`,
      {
        level: 'error',
      },
    )
    return null
  }
}

export const getPluginCommands = memoize(async (): Promise<Command[]> => {
  // --bare: skip marketplace plugin auto-load. Explicit --plugin-dir still
  // works — getInlinePlugins() is set by main.tsx from --plugin-dir.
  // loadAllPluginsCacheOnly already short-circuits to inline-only when
  // inlinePlugins.length > 0.
  if (isBareMode() && (getInlinePlugins()?.length ?? 0) === 0) {
    return []
  }
  // Only load commands from enabled plugins
  const { enabled, errors } = await loadAllPluginsCacheOnly()

  if (errors.length > 0) {
    logForDebugging(
      `Plugin loading errors: ${errors.map(e => getPluginErrorMessage(e)).join(', ')}`,
    )
  }

  // Process plugins in parallel; each plugin has its own loadedPaths scope
  const perPluginCommands = await Promise.all(
    enabled.map(async (plugin): Promise<Command[]> => {
      // Track loaded file paths to prevent duplicates within this plugin
      const loadedPaths = new Set<string>()
      const pluginCommands: Command[] = []

      // Load commands from default commands directory
      if (plugin.commandsPath) {
        try {
          const commands = await loadCommandsFromDirectory(
            plugin.commandsPath,
            plugin.name,
            plugin.source,
            plugin.manifest,
            plugin.path,
            { isSkillMode: false },
            loadedPaths,
          )
          pluginCommands.push(...commands)

          if (commands.length > 0) {
            logForDebugging(
              `Loaded ${commands.length} commands from plugin ${plugin.name} default directory`,
            )
          }
        } catch (error) {
          logForDebugging(
            `Failed to load commands from plugin ${plugin.name} default directory: ${error}`,
            { level: 'error' },
          )
        }
      }

      // Load commands from additional paths specified in manifest
      if (plugin.commandsPaths) {
        logForDebugging(
          `Plugin ${plugin.name} has commandsPaths: ${plugin.commandsPaths.join(', ')}`,
        )
        // Process all commandsPaths in parallel. isDuplicatePath is synchronous
        // (check-and-add), so concurrent access to loadedPaths is safe.
        const pathResults = await Promise.all(
          plugin.commandsPaths.map(async (commandPath): Promise<Command[]> => {
            try {
              const fs = getFsImplementation()
              const stats = await fs.stat(commandPath)
              logForDebugging(
                `Checking commandPath ${commandPath} - isDirectory: ${stats.isDirectory()}, isFile: ${stats.isFile()}`,
              )

              if (stats.isDirectory()) {
                // Load all .md files and skill directories from directory
                const commands = await loadCommandsFromDirectory(
                  commandPath,
                  plugin.name,
                  plugin.source,
                  plugin.manifest,
                  plugin.path,
                  { isSkillMode: false },
                  loadedPaths,
                )

                if (commands.length > 0) {
                  logForDebugging(
                    `Loaded ${commands.length} commands from plugin ${plugin.name} custom path: ${commandPath}`,
                  )
                } else {
                  logForDebugging(
                    `Warning: No commands found in plugin ${plugin.name} custom directory: ${commandPath}. Expected .md files or SKILL.md in subdirectories.`,
                    { level: 'warn' },
                  )
                }
                return commands
              } else if (stats.isFile() && commandPath.endsWith('.md')) {
                if (isDuplicatePath(commandPath, loadedPaths)) {
                  return []
                }

                // Load single command file
                const content = await fs.readFile(commandPath, {
                  encoding: 'utf-8',
                })
                const { frontmatter, content: markdownContent } =
                  parseFrontmatter(content, commandPath)

                // Check if there's metadata for this command (object-mapping format)
                let commandName: string | undefined
                let metadataOverride: CommandMetadata | undefined

                if (plugin.commandsMetadata) {
                  // Find metadata by matching the command's absolute path to the metadata source
                  // Convert metadata.source (relative to plugin root) to absolute path for comparison
                  for (const [name, metadata] of Object.entries(
                    plugin.commandsMetadata,
                  ) as [string, CommandMetadata][]) {
                    if (metadata.source) {
                      const fullMetadataPath = join(
                        plugin.path,
                        metadata.source,
                      )
                      if (commandPath === fullMetadataPath) {
                        commandName = `${plugin.name}:${name}`
                        metadataOverride = metadata
                        break
                      }
                    }
                  }
                }

                // Fall back to filename-based naming if no metadata
                if (!commandName) {
                  commandName = `${plugin.name}:${basename(commandPath).replace(/\.md$/, '')}`
                }

                // Apply metadata overrides to frontmatter
                const finalFrontmatter = metadataOverride
                  ? {
                      ...frontmatter,
                      ...(metadataOverride.description && {
                        description: metadataOverride.description,
                      }),
                      ...(metadataOverride.argumentHint && {
                        'argument-hint': metadataOverride.argumentHint,
                      }),
                      ...(metadataOverride.model && {
                        model: metadataOverride.model,
                      }),
                      ...(metadataOverride.allowedTools && {
                        'allowed-tools':
                          metadataOverride.allowedTools.join(','),
                      }),
                    }
                  : frontmatter

                const file: PluginMarkdownFile = {
                  filePath: commandPath,
                  baseDir: dirname(commandPath),
                  frontmatter: finalFrontmatter,
                  content: markdownContent,
                }

                const command = createPluginCommand(
                  commandName,
                  file,
                  plugin.source,
                  plugin.manifest,
                  plugin.path,
                  false,
                )

                if (command) {
                  logForDebugging(
                    `Loaded command from plugin ${plugin.name} custom file: ${commandPath}${metadataOverride ? ' (with metadata override)' : ''}`,
                  )
                  return [command]
                }
              }
              return []
            } catch (error) {
              logForDebugging(
                `Failed to load commands from plugin ${plugin.name} custom path ${commandPath}: ${error}`,
                { level: 'error' },
              )
              return []
            }
          }),
        )
        for (const commands of pathResults) {
          pluginCommands.push(...commands)
        }
      }

      // Load commands with inline content (no source file)
      // Note: Commands with source files were already loaded in the previous loop
      // when iterating through commandsPaths. This loop handles metadata entries
      // that specify inline content instead of file references.
      if (plugin.commandsMetadata) {
        for (const [name, metadata] of Object.entries(
          plugin.commandsMetadata,
        ) as [string, CommandMetadata][]) {
          // Only process entries with inline content (no source)
          if (metadata.content && !metadata.source) {
            try {
              // Parse inline content for frontmatter
              const { frontmatter, content: markdownContent } =
                parseFrontmatter(
                  metadata.content,
                  `<inline:${plugin.name}:${name}>`,
                )

              // Apply metadata overrides to frontmatter
              const finalFrontmatter: FrontmatterData = {
                ...frontmatter,
                ...(metadata.description && {
                  description: metadata.description,
                }),
                ...(metadata.argumentHint && {
                  'argument-hint': metadata.argumentHint,
                }),
                ...(metadata.model && {
                  model: metadata.model,
                }),
                ...(metadata.allowedTools && {
                  'allowed-tools': metadata.allowedTools.join(','),
                }),
              }

              const commandName = `${plugin.name}:${name}`
              const file: PluginMarkdownFile = {
                filePath: `<inline:${commandName}>`, // Virtual path for inline content
                baseDir: plugin.path, // Use plugin root as base directory
                frontmatter: finalFrontmatter,
                content: markdownContent,
              }

              const command = createPluginCommand(
                commandName,
                file,
                plugin.source,
                plugin.manifest,
                plugin.path,
                false,
              )

              if (command) {
                pluginCommands.push(command)
                logForDebugging(
                  `Loaded inline content command from plugin ${plugin.name}: ${commandName}`,
                )
              }
            } catch (error) {
              logForDebugging(
                `Failed to load inline content command ${name} from plugin ${plugin.name}: ${error}`,
                { level: 'error' },
              )
            }
          }
        }
      }
      return pluginCommands
    }),
  )

  const allCommands = perPluginCommands.flat()
  logForDebugging(`Total plugin commands loaded: ${allCommands.length}`)
  // Ant v2.1.136 LzH (2643.js) — emit `tengu_plugin_name_collision` when
  // two plugin sources contribute a command with the same name. The
  // loader's own deterministic ordering already picked a winner; this
  // event is observability-only. LzH walks all entries in source-push
  // order, dedupes per-name sources, and tags the LAST source as
  // `winner_source` when `resolves=true` is supplied. Wrap in try/catch
  // so telemetry can never block plugin command loading.
  try {
    logNameCollision({
      itemType: 'command',
      entries: allCommands.map(cmd => ({
        name: cmd.name,
        source:
          (cmd as { source?: string }).source ??
          (cmd as { loadedFrom?: string }).loadedFrom ??
          'plugin',
      })),
      resolves: true,
    })
  } catch {
    // collision telemetry must not block plugin command loading
  }
  return allCommands
})

export function clearPluginCommandCache(): void {
  getPluginCommands.cache?.clear?.()
}

/**
 * Loads skills from plugin skills directories
 * Skills are directories containing SKILL.md files
 */
async function loadSkillsFromDirectory(
  skillsPath: string,
  pluginName: string,
  sourceName: string,
  pluginManifest: PluginManifest,
  pluginPath: string,
  loadedPaths: Set<string>,
): Promise<Command[]> {
  const fs = getFsImplementation()
  const skills: Command[] = []

  // First, check if skillsPath itself contains SKILL.md (direct skill directory)
  const directSkillPath = join(skillsPath, 'SKILL.md')
  let directSkillContent: string | null = null
  try {
    directSkillContent = await fs.readFile(directSkillPath, {
      encoding: 'utf-8',
    })
  } catch (e: unknown) {
    if (!isENOENT(e)) {
      logForDebugging(`Failed to load skill from ${directSkillPath}: ${e}`, {
        level: 'error',
      })
      return skills
    }
    // ENOENT: no direct SKILL.md, fall through to scan subdirectories
  }

  if (directSkillContent !== null) {
    // This is a direct skill directory, load the skill from here
    if (isDuplicatePath(directSkillPath, loadedPaths)) {
      return skills
    }
    try {
      const { frontmatter, content: markdownContent } = parseFrontmatter(
        directSkillContent,
        directSkillPath,
      )

      const skillName = `${pluginName}:${basename(skillsPath)}`

      const file: PluginMarkdownFile = {
        filePath: directSkillPath,
        baseDir: dirname(directSkillPath),
        frontmatter,
        content: markdownContent,
      }

      const skill = createPluginCommand(
        skillName,
        file,
        sourceName,
        pluginManifest,
        pluginPath,
        true, // isSkill
        { isSkillMode: true }, // config
      )

      if (skill) {
        skills.push(skill)
      }
    } catch (error) {
      logForDebugging(
        `Failed to load skill from ${directSkillPath}: ${error}`,
        {
          level: 'error',
        },
      )
    }
    return skills
  }

  // Otherwise, scan for subdirectories containing SKILL.md files
  let entries
  try {
    entries = await fs.readdir(skillsPath)
  } catch (e: unknown) {
    if (!isENOENT(e)) {
      logForDebugging(
        `Failed to load skills from directory ${skillsPath}: ${e}`,
        { level: 'error' },
      )
    }
    return skills
  }

  await Promise.all(
    entries.map(async entry => {
      // Accept both directories and symlinks (symlinks may point to skill directories)
      if (!entry.isDirectory() && !entry.isSymbolicLink()) {
        return
      }

      const skillDirPath = join(skillsPath, entry.name)
      const skillFilePath = join(skillDirPath, 'SKILL.md')

      // Try to read SKILL.md directly; skip if it doesn't exist
      let content: string
      try {
        content = await fs.readFile(skillFilePath, { encoding: 'utf-8' })
      } catch (e: unknown) {
        if (!isENOENT(e)) {
          logForDebugging(`Failed to load skill from ${skillFilePath}: ${e}`, {
            level: 'error',
          })
        }
        return
      }

      if (isDuplicatePath(skillFilePath, loadedPaths)) {
        return
      }

      try {
        const { frontmatter, content: markdownContent } = parseFrontmatter(
          content,
          skillFilePath,
        )

        const skillName = `${pluginName}:${entry.name}`

        const file: PluginMarkdownFile = {
          filePath: skillFilePath,
          baseDir: dirname(skillFilePath),
          frontmatter,
          content: markdownContent,
        }

        const skill = createPluginCommand(
          skillName,
          file,
          sourceName,
          pluginManifest,
          pluginPath,
          true, // isSkill
          { isSkillMode: true }, // config
        )

        if (skill) {
          skills.push(skill)
        }
      } catch (error) {
        logForDebugging(
          `Failed to load skill from ${skillFilePath}: ${error}`,
          { level: 'error' },
        )
      }
    }),
  )

  return skills
}

export const getPluginSkills = memoize(async (): Promise<Command[]> => {
  // --bare: same gate as getPluginCommands above — honor explicit
  // --plugin-dir, skip marketplace auto-load.
  if (isBareMode() && (getInlinePlugins()?.length ?? 0) === 0) {
    return []
  }
  // Only load skills from enabled plugins
  const { enabled, errors } = await loadAllPluginsCacheOnly()

  if (errors.length > 0) {
    logForDebugging(
      `Plugin loading errors: ${errors.map(e => getPluginErrorMessage(e)).join(', ')}`,
    )
  }

  logForDebugging(
    `getPluginSkills: Processing ${enabled.length} enabled plugins`,
  )

  // Process plugins in parallel; each plugin has its own loadedPaths scope
  const perPluginSkills = await Promise.all(
    enabled.map(async (plugin): Promise<Command[]> => {
      // Track loaded file paths to prevent duplicates within this plugin
      const loadedPaths = new Set<string>()
      const pluginSkills: Command[] = []

      logForDebugging(
        `Checking plugin ${plugin.name}: skillsPath=${plugin.skillsPath ? 'exists' : 'none'}, skillsPaths=${plugin.skillsPaths ? plugin.skillsPaths.length : 0} paths`,
      )
      // Load skills from default skills directory
      if (plugin.skillsPath) {
        logForDebugging(
          `Attempting to load skills from plugin ${plugin.name} default skillsPath: ${plugin.skillsPath}`,
        )
        try {
          const skills = await loadSkillsFromDirectory(
            plugin.skillsPath,
            plugin.name,
            plugin.source,
            plugin.manifest,
            plugin.path,
            loadedPaths,
          )
          pluginSkills.push(...skills)

          logForDebugging(
            `Loaded ${skills.length} skills from plugin ${plugin.name} default directory`,
          )
        } catch (error) {
          logForDebugging(
            `Failed to load skills from plugin ${plugin.name} default directory: ${error}`,
            { level: 'error' },
          )
        }
      }

      // Load skills from additional paths specified in manifest
      if (plugin.skillsPaths) {
        logForDebugging(
          `Attempting to load skills from plugin ${plugin.name} skillsPaths: ${plugin.skillsPaths.join(', ')}`,
        )
        // Process all skillsPaths in parallel. isDuplicatePath is synchronous
        // (check-and-add), so concurrent access to loadedPaths is safe.
        const pathResults = await Promise.all(
          plugin.skillsPaths.map(async (skillPath): Promise<Command[]> => {
            try {
              logForDebugging(
                `Loading from skillPath: ${skillPath} for plugin ${plugin.name}`,
              )
              const skills = await loadSkillsFromDirectory(
                skillPath,
                plugin.name,
                plugin.source,
                plugin.manifest,
                plugin.path,
                loadedPaths,
              )

              logForDebugging(
                `Loaded ${skills.length} skills from plugin ${plugin.name} custom path: ${skillPath}`,
              )
              return skills
            } catch (error) {
              logForDebugging(
                `Failed to load skills from plugin ${plugin.name} custom path ${skillPath}: ${error}`,
                { level: 'error' },
              )
              return []
            }
          }),
        )
        for (const skills of pathResults) {
          pluginSkills.push(...skills)
        }
      }
      return pluginSkills
    }),
  )

  const allSkills = perPluginSkills.flat()
  logForDebugging(`Total plugin skills loaded: ${allSkills.length}`)
  return allSkills
})

export function clearPluginSkillsCache(): void {
  getPluginSkills.cache?.clear?.()
}

